import { createFileRegistry, fromBinary } from "@bufbuild/protobuf";
import { FileDescriptorSetSchema } from "@bufbuild/protobuf/wkt";

const registry = createFileRegistry(fromBinary(FileDescriptorSetSchema, Uint8Array.from(atob(""), char => char.charCodeAt(0))));
export const LogsRequest = registry.getMessage("opentelemetry.proto.collector.logs.v1.ExportLogsServiceRequest")!;
export const LogsResponse = registry.getMessage("opentelemetry.proto.collector.logs.v1.ExportLogsServiceResponse")!;
export const RpcStatus = registry.getMessage("google.rpc.Status")!;
